var Z85_CHARS='0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ.-:+=^!/*?&<>()[]{}@%$#';
function b85StrToBytes(s){
  var out=[], str=String(s);
  for(var i=0;i<str.length;i++){
    var c=str.codePointAt(i);
    if(c>0xFFFF) i++;
    if(c<0x80) out.push(c);
    else if(c<0x800){ out.push(0xC0|(c>>6), 0x80|(c&63)); }
    else if(c<0x10000){ out.push(0xE0|(c>>12), 0x80|((c>>6)&63), 0x80|(c&63)); }
    else { out.push(0xF0|(c>>18), 0x80|((c>>12)&63), 0x80|((c>>6)&63), 0x80|(c&63)); }
  }
  return out;
}
function b85BytesToStr(bytes){
  var s='';
  for(var i=0;i<bytes.length;){
    var b=bytes[i];
    if(b<0x80){ s+=String.fromCharCode(b); i++; }
    else if(b<0xE0){ s+=String.fromCharCode(((b&31)<<6)|(bytes[i+1]&63)); i+=2; }
    else if(b<0xF0){ s+=String.fromCharCode(((b&15)<<12)|((bytes[i+1]&63)<<6)|(bytes[i+2]&63)); i+=3; }
    else { var cp=((b&7)<<18)|((bytes[i+1]&63)<<12)|((bytes[i+2]&63)<<6)|(bytes[i+3]&63);
      s+=String.fromCodePoint(cp); i+=4; }
  }
  return s;
}
function b85Encode(bytes){
  var out='';
  for(var i=0;i<bytes.length;i+=4){
    var chunk=bytes.slice(i,i+4), pad=4-chunk.length;
    while(chunk.length<4) chunk.push(0);
    var v=((chunk[0]*16777216)+(chunk[1]*65536)+(chunk[2]*256)+chunk[3]);
    if(v===0&&pad===0){ out+='z'; continue; }
    var cs=[];
    for(var j=0;j<5;j++){ cs.unshift(String.fromCharCode(33+v%85)); v=Math.floor(v/85); }
    out+=cs.join('').slice(0,5-pad);
  }
  return { value:'<~'+out+'~>', error:null };
}
function b85Decode(text){
  var s=String(text).replace(/\s+/g,'');
  if(s.slice(0,2)==='<~') s=s.slice(2);
  if(s.slice(-2)==='~>') s=s.slice(0,-2);
  var out=[], group=[];
  for(var i=0;i<s.length;i++){
    var ch=s[i];
    if(ch==='z'){
      if(group.length) return { value:null, error:'z 出现在组内（位置 '+i+'）' };
      out.push(0,0,0,0); continue;
    }
    var c=ch.charCodeAt(0);
    if(c<33||c>117) return { value:null, error:'非法字符 "'+ch+'"（位置 '+i+'）' };
    group.push(c-33);
    if(group.length===5){
      var v=0;
      for(var j=0;j<5;j++) v=v*85+group[j];
      if(v>4294967295) return { value:null, error:'组溢出（位置 '+i+'）' };
      out.push(Math.floor(v/16777216)&255,(v>>>16)&255,(v>>>8)&255,v&255);
      group=[];
    }
  }
  if(group.length===1) return { value:null, error:'尾组长度不能为 1' };
  if(group.length){
    var pad=5-group.length, g2=group.slice();
    for(var k=0;k<pad;k++) g2.push(84);
    var v2=0;
    for(var j2=0;j2<5;j2++) v2=v2*85+g2[j2];
    var bs=[Math.floor(v2/16777216)&255,(v2>>>16)&255,(v2>>>8)&255,v2&255];
    for(var t=0;t<4-pad;t++) out.push(bs[t]);
  }
  return { value:out, error:null };
}
function z85Encode(bytes){
  if(bytes.length%4!==0) return { value:null, error:'Z85 要求字节数为 4 的倍数（当前 '+bytes.length+'）' };
  var out='';
  for(var i=0;i<bytes.length;i+=4){
    var v=(bytes[i]*16777216)+(bytes[i+1]*65536)+(bytes[i+2]*256)+bytes[i+3];
    var cs=[];
    for(var j=0;j<5;j++){ cs.unshift(Z85_CHARS[v%85]); v=Math.floor(v/85); }
    out+=cs.join('');
  }
  return { value:out, error:null };
}
function z85Decode(text){
  var s=String(text).replace(/\s+/g,'');
  if(s.length%5!==0) return { value:null, error:'Z85 字符数须为 5 的倍数（当前 '+s.length+'）' };
  var out=[];
  for(var i=0;i<s.length;i+=5){
    var v=0;
    for(var j=0;j<5;j++){
      var idx=Z85_CHARS.indexOf(s[i+j]);
      if(idx<0) return { value:null, error:'非法字符 "'+s[i+j]+'"（位置 '+(i+j)+'）' };
      v=v*85+idx;
    }
    if(v>4294967295) return { value:null, error:'组溢出（位置 '+i+'）' };
    out.push(Math.floor(v/16777216)&255,(v>>>16)&255,(v>>>8)&255,v&255);
  }
  return { value:out, error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { b85Encode:b85Encode, b85Decode:b85Decode, z85Encode:z85Encode, z85Decode:z85Decode,
    b85StrToBytes:b85StrToBytes, b85BytesToStr:b85BytesToStr };
}
if (typeof window !== 'undefined') {
  window.Base85ForgePure = { b85Encode:b85Encode, b85Decode:b85Decode, z85Encode:z85Encode, z85Decode:z85Decode,
    b85StrToBytes:b85StrToBytes, b85BytesToStr:b85BytesToStr };
}
